CARD_TITLES = {"INTH · 08":"inspection","INTH":"inspections","QTTH lines":"quoteLines","QTTH":"quoteLines","RPTH / PMTH · 09 / 10 / 11":"repairJob","RPTH / PMTH":"repairJobs","12 / 13":"acceptanceRecord","13 Customer Acceptance":"acceptance","TITH + IVTH":"invoicing","TITH / IVTH":"invoices","Payment":"payment","ERTH · 07 Equipment receiving (workshop)":"receiving","10 · Case archive → knowledge":"archive"}

def rewrite(path: pathlib.Path):
    s = path.read_text(encoding="utf8"); o = s
    for lit, key in CARD_TITLES.items():
        s = s.replace(f'title="{lit}"', f'title={{t("{key}")}}')
    for lit in order:
        key = LIT[lit]; q = re.escape(lit)
        s = re.sub(rf'placeholder="{q}"', f'placeholder={{t("{key}")}}', s)
        s = re.sub(rf'(?<![=-])>{q}<', f'>{{t("{key}")}}<', s)
        s = re.sub(rf'(<option[^>]*>){q}(</option>)', rf'\1{{t("{key}")}}\2', s)
    if s != o: path.write_text(s, encoding="utf8"); print("rewrote", path.relative_to(ROOT))

for p in list((ROOT/"src/app").rglob("*.tsx")) + list((ROOT/"src/components").rglob("*.tsx")):
    rewrite(p)
